WITH base AS (SELECT id, session_id, page, event_time, CASE WHEN event_type = 'purchase' THEN 1 ELSE 0 END AS is_purchase FROM web_events WHERE session_id IN (13, 37)) SELECT p.country, s.page, COUNT(*) AS cnt, ROUND(AVG(s.is_purchase), 2) AS avg_is_purchase, GROUPING_ID() AS gid FROM base s LEFT JOIN sessions p ON s.session_id = p.id GROUP BY ROLLUP (p.country, s.page) ORDER BY cnt NULLS LAST;
